"""Fail-closed original Engineer-permission, marking and lawful-direction review."""
from __future__ import annotations
import hashlib
import json
import math
from pathlib import Path
ASSIGNMENT='testing__C377875__LVMC-11-52-070__motor_vehicle_driver'
SOURCE_NAMES=('map','roadway','marking','authority','vehicle','purpose')

def point(v):
    if not isinstance(v,list) or len(v)!=2 or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) for x in v):
        raise ValueError('finite two-coordinate point required')
    return float(v[0]),float(v[1])

def inside(p,vertices):
    if not isinstance(vertices,list) or len(vertices)<3:raise ValueError('permission extent polygon required')
    poly=[point(x) for x in vertices];x,y=p;hit=False
    for a,b in zip(poly,poly[1:]+poly[:1]):
        if (a[1]>y)!=(b[1]>y) and x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]:hit=not hit
    return hit

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()

def unit(v):
    x,y=point(v);length=math.hypot(x,y)
    if length<.01:raise ValueError('lawful traffic direction vector required')
    return x/length,y/length

def load_site(path,case_id):
    path=Path(path).resolve();site=json.loads(path.read_text())
    if site.get('assignment_id')!=ASSIGNMENT or site.get('case_id')!=case_id or not case_id.startswith(ASSIGNMENT+'__'):
        raise ValueError('wrong exact Engineer-angle-parking assignment or case')
    suffix=case_id.rsplit('__',1)[-1]
    try:activity,orientation=suffix.split('_',1)
    except ValueError as e:raise ValueError('unsupported exact case') from e
    if activity not in {'stand','park'} or orientation not in {'forward','opposing'}:
        raise ValueError('unsupported exact stand/park orientation')
    if site.get('requested_activity')!=activity or site.get('requested_orientation')!=orientation:
        raise ValueError('reviewed site differs from exact case request')
    refs=site.get('sources',{})
    if not isinstance(refs,dict) or set(SOURCE_NAMES)-set(refs):raise ValueError('all original source packets required')
    records={}
    for name in SOURCE_NAMES:
        ref=refs[name];rel=ref.get('path') if isinstance(ref,dict) else None
        if not isinstance(rel,str) or Path(rel).is_absolute() or '..' in Path(rel).parts:
            raise ValueError('contained relative original source path required: '+name)
        target=(path.parent/rel).resolve()
        if not target.is_relative_to(path.parent) or not target.is_file() or sha(target)!=ref.get('sha256'):
            raise ValueError('original source missing or changed: '+name)
        records[name]=json.loads(target.read_text())
    road=records['roadway'];authority=records['authority'];marking=records['marking']
    if road.get('district')!='business' or road.get('highway_status')!='reviewed_original' or road.get('jurisdiction')!='city':
        raise ValueError('original city business-district street review required')
    lawful=unit(road.get('lawful_traffic_vector_xy'))
    if road.get('lawful_direction_status')!='reviewed_original':
        raise ValueError('original lawful traffic movement direction required')
    if authority.get('determining_office')!='City Traffic Engineer' or authority.get('permission_status')!='reviewed_original' or authority.get('angle_parking_permitted') is not True or not authority.get('source'):
        raise ValueError('original Engineer determination and permission required')
    if marking.get('marking_status')!='reviewed_original' or not marking.get('content_review') or marking.get('permission_indicated') is not True:
        raise ValueError('original sign or marking indicating permitted angle parking required')
    if not inside(point(site.get('target_xy')),authority.get('permission_extent_polygon_xy')):
        raise ValueError('target outside reviewed permission extent')
    if not inside(point(site.get('target_xy')),marking.get('governed_space_polygon_xy')):
        raise ValueError('target outside reviewed marking extent')
    if math.dist(point(site.get('target_xy')),point(site.get('approach_xy')))<8:
        raise ValueError('construction approach too short')
    if records['purpose'].get('activity_review')!='reviewed_original' or records['purpose'].get('category')!=activity:
        raise ValueError('original stand/park purpose and service review required')
    if not records['vehicle'].get('source') or records['vehicle'].get('front_direction_status')!='reviewed_original':
        raise ValueError('original vehicle/front identification required')
    if not isinstance(records['map'].get('opendrive_sha256'),str) or len(records['map']['opendrive_sha256'])!=64:
        raise ValueError('original OpenDRIVE source required')
    if not isinstance(site.get('map_id'),str) or not isinstance(site.get('road_id'),int) or not site.get('vehicle_blueprint_id'):
        raise ValueError('Native map, road and vehicle identity required')
    if not marking.get('prop_blueprint_id') or not isinstance(marking.get('prop_pose'),dict):
        raise ValueError('reviewed marking prop construction required')
    pose=marking['prop_pose']
    if any(isinstance(pose.get(k),bool) or not isinstance(pose.get(k),(int,float)) or not math.isfinite(pose[k]) for k in ('x','y','z','yaw_deg')):
        raise ValueError('finite marking prop pose required')
    for key in ('approach_heading_degrees','target_heading_degrees'):
        value=site.get(key)
        if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):raise ValueError('finite '+key+' required')
    heading=math.radians(site['target_heading_degrees'])
    dot=math.cos(heading)*lawful[0]+math.sin(heading)*lawful[1]
    if orientation=='forward' and dot<.95:raise ValueError('target front not constructed toward lawful traffic')
    if orientation=='opposing' and dot>-.95:raise ValueError('target front not constructed opposing lawful traffic')
    return site,records

"""Source-bound vehicle-front versus lawful-traffic direction measurement."""
from __future__ import annotations
import math

def finite(value,label):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):raise ValueError('finite '+label+' required')
    return float(value)

def unit(vector):
    if not isinstance(vector,list) or len(vector)!=2:raise ValueError('original lawful direction vector required')
    x,y=[finite(v,'lawful vector component') for v in vector];size=math.hypot(x,y)
    if size<.01:raise ValueError('original lawful direction vector degenerate')
    return x/size,y/size

def measure(packet):
    if not isinstance(packet,dict) or packet.get('source_kind') not in {'original_native','diagnostic_native_shape'}:
        raise ValueError('original Native or explicit diagnostic source required')
    diagnostic=packet['source_kind']=='diagnostic_native_shape'
    if diagnostic and packet.get('diagnostic_fixture') is not True:raise ValueError('diagnostic provenance required')
    for key in ('assignment_id','case_id','capture_source_sha256','marking_source_sha256','frame_map_sha256'):
        if not isinstance(packet.get(key),str) or not packet[key]:raise ValueError('missing source binding: '+key)
    if packet['assignment_id']!='testing__C377875__LVMC-11-52-070__motor_vehicle_driver' or not packet['case_id'].startswith(packet['assignment_id']+'__'):
        raise ValueError('exact assignment or case differs')
    marking=packet.get('marking',{});authority=packet.get('authority',{})
    if (marking.get('marking_status')!='reviewed_original' or marking.get('permission_indicated') is not True
        or authority.get('determining_office')!='City Traffic Engineer' or authority.get('permission_status')!='reviewed_original'
        or authority.get('angle_parking_permitted') is not True):raise ValueError('original Engineer permission and marking required')
    if packet.get('roadway_source_review')!='reviewed_original' or packet.get('lawful_direction_status')!='reviewed_original':
        raise ValueError('original roadway and lawful direction review required')
    if packet.get('purpose_review',{}).get('activity_review')!='reviewed_original':raise ValueError('original stand/park purpose review required')
    lawful=unit(packet.get('lawful_traffic_vector_xy'));frames=packet.get('frames')
    if not isinstance(frames,list) or not frames:raise ValueError('original frame history required')
    expected=frames[0].get('frame');angles=[];front_dots=[];halt=[]
    if isinstance(expected,bool) or not isinstance(expected,int):raise ValueError('invalid original frame identity')
    for row in frames:
        if row.get('frame')!=expected:raise ValueError('noncontiguous original frame history')
        expected+=1
        if row.get('halt_observed') is True:
            yaw=math.radians(finite(row.get('body_yaw_degrees'),'vehicle front yaw'))
            dot=math.cos(yaw)*lawful[0]+math.sin(yaw)*lawful[1]
            angles.append(math.degrees(math.acos(max(-1,min(1,dot)))))
            front_dots.append(dot);halt.append(row['frame'])
        elif row.get('halt_observed') is not False:raise ValueError('halt observation missing')
    if len(halt)<2:raise ValueError('two observed standing/parking frames required')
    return {'format':'worker-lawful-traffic-orientation-measurement','assignment_id':packet['assignment_id'],
            'case_id':packet['case_id'],'source_bindings':{k:packet[k] for k in ('capture_source_sha256','marking_source_sha256','frame_map_sha256')},
            'diagnostic_fixture':diagnostic,'halt_first_frame':halt[0],'halt_last_frame':halt[-1],
            'halt_frame_count':len(halt),'front_vs_lawful_direction_min_degrees':min(angles),
            'front_vs_lawful_direction_max_degrees':max(angles),
            'front_vs_lawful_direction_mean_degrees':sum(angles)/len(angles),
            'front_dot_lawful_direction_mean':sum(front_dots)/len(front_dots),
            'legal_classification':'unreviewed','physical_original_review':'pending'}

"""Focused CPU checks for Engineer-permitted front-direction construction."""
import hashlib
import json
import os
import sys
import tempfile
import unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from orientation_site import load_site
from orientation_measurement import measure
from orientation_native import control
from runner import selected_config

A='testing__C377875__LVMC-11-52-070__motor_vehicle_driver'

def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()

def make_site(root,suffix):
    activity,orientation=suffix.split('_',1);root=Path(root)
    records={'map':{'opendrive_sha256':'a'*64},'roadway':{'district':'business','jurisdiction':'city','highway_status':'reviewed_original','lawful_direction_status':'reviewed_original','lawful_traffic_vector_xy':[1,0]},'marking':{'marking_status':'reviewed_original','permission_indicated':True,'content_review':'original marking reviewed','governed_space_polygon_xy':[[0,0],[10,0],[10,10],[0,10]],'prop_blueprint_id':'static.prop.sign','prop_pose':{'x':2,'y':2,'z':0,'yaw_deg':0}},'authority':{'source':'signed Engineer record','determining_office':'City Traffic Engineer','permission_status':'reviewed_original','angle_parking_permitted':True,'permission_extent_polygon_xy':[[0,0],[10,0],[10,10],[0,10]]},'vehicle':{'source':'reviewed front identification','front_direction_status':'reviewed_original'},'purpose':{'activity_review':'reviewed_original','category':activity}}
    refs={}
    for name,value in records.items():
        path=root/(name+'.json');path.write_text(json.dumps(value)+'\n');refs[name]={'path':path.name,'sha256':sha(path)}
    site={'assignment_id':A,'case_id':A+'__'+suffix,'sources':refs,'target_xy':[5,5],'approach_xy':[5,20],'requested_activity':activity,'requested_orientation':orientation,'map_id':'Town01','road_id':1,'vehicle_blueprint_id':'vehicle.tesla.model3','approach_heading_degrees':-90,'target_heading_degrees':0 if orientation=='forward' else 180}
    path=root/'site.json';path.write_text(json.dumps(site)+'\n');return path

class SiteTests(unittest.TestCase):
    def test_both_exact_front_directions(self):
        with tempfile.TemporaryDirectory(dir=os.environ.get('TMPDIR')) as tmp:
            path=make_site(tmp,'stand_forward');site,records=load_site(path,A+'__stand_forward');self.assertEqual(records['authority']['determining_office'],'City Traffic Engineer')
            path=make_site(tmp,'park_opposing');site,records=load_site(path,A+'__park_opposing');self.assertEqual(site['target_heading_degrees'],180)
    def test_reject_missing_engineer_determination(self):
        with tempfile.TemporaryDirectory(dir=os.environ.get('TMPDIR')) as tmp:
            path=make_site(tmp,'stand_forward');data=json.loads((Path(tmp)/'authority.json').read_text());data['determining_office']='unknown';p=Path(tmp)/'authority.json';p.write_text(json.dumps(data)+'\n');site=json.loads(path.read_text());site['sources']['authority']['sha256']=sha(p);path.write_text(json.dumps(site)+'\n')
            with self.assertRaisesRegex(ValueError,'Engineer determination'):load_site(path,A+'__stand_forward')
    def test_reject_wrong_front(self):
        with tempfile.TemporaryDirectory(dir=os.environ.get('TMPDIR')) as tmp:
            path=make_site(tmp,'stand_forward');site=json.loads(path.read_text());site['target_heading_degrees']=180;path.write_text(json.dumps(site)+'\n')
            with self.assertRaisesRegex(ValueError,'target front'):load_site(path,A+'__stand_forward')
    def test_reject_outside_permission(self):
        with tempfile.TemporaryDirectory(dir=os.environ.get('TMPDIR')) as tmp:
            path=make_site(tmp,'stand_forward');site=json.loads(path.read_text());site['target_xy']=[20,20];path.write_text(json.dumps(site)+'\n')
            with self.assertRaisesRegex(ValueError,'permission extent'):load_site(path,A+'__stand_forward')

class MeasurementTests(unittest.TestCase):
    def packet(self,yaw):
        return {'source_kind':'diagnostic_native_shape','diagnostic_fixture':True,'assignment_id':A,'case_id':A+'__stand_forward','capture_source_sha256':'a','marking_source_sha256':'b','frame_map_sha256':'c','marking':{'marking_status':'reviewed_original','permission_indicated':True},'authority':{'determining_office':'City Traffic Engineer','permission_status':'reviewed_original','angle_parking_permitted':True},'roadway_source_review':'reviewed_original','lawful_direction_status':'reviewed_original','purpose_review':{'activity_review':'reviewed_original'},'lawful_traffic_vector_xy':[1,0],'frames':[{'frame':i,'halt_observed':True,'body_yaw_degrees':yaw} for i in range(3)]}
    def test_forward_and_opposing_observable(self):
        self.assertAlmostEqual(measure(self.packet(0))['front_vs_lawful_direction_mean_degrees'],0)
        self.assertAlmostEqual(measure(self.packet(180))['front_vs_lawful_direction_mean_degrees'],180)
    def test_reject_unreviewed_direction(self):
        packet=self.packet(0);packet['lawful_direction_status']='unreviewed'
        with self.assertRaisesRegex(ValueError,'lawful direction'):measure(packet)

class ControlTests(unittest.TestCase):
    def test_stand_depart_and_park_hold(self):
        command,state,_=control((0,0),0,0,(0,0),0,True,170,'stand',600)
        self.assertEqual(state,'depart')
        command,state,_=control((0,0),0,0,(0,0),0,True,170,'park',600)
        self.assertEqual(state,'hold');self.assertTrue(command['hand_brake'])
    def test_config_identity(self):self.assertEqual(selected_config()['law_id'],'LVMC-11-52-070')
if __name__=='__main__':unittest.main()
